files.content:
.login-form {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 14px;
}

.login-form .field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
}

.login-form .remember {
  display: flex;
  align-items: center;
  gap: 8px;
}

.login-form .actions button {
  width: 100%;
  height: 40px;
}
